-- Canonical metadata projection used unchanged by capture, preflight, assertions,
-- rollback and local tests. Excludes OIDs/timestamps; includes ACL grantors/options.
select jsonb_build_object(
 'constraints',(select jsonb_agg(jsonb_build_object('name',conname,'definition',pg_get_constraintdef(oid)) order by conname) from pg_constraint where conrelid='public.profiles'::regclass and contype <> 'n'),
 'indexes',(select jsonb_agg(jsonb_build_object('name',indexname,'definition',indexdef) order by indexname) from pg_indexes where schemaname='public' and tablename='profiles'),
 'relation',(select jsonb_build_object('owner',pg_get_userbyid(relowner),'rls',relrowsecurity,'force_rls',relforcerowsecurity,'acl',(select jsonb_agg(v::text order by v::text) from unnest(coalesce(relacl,acldefault('r',relowner))) a(v))) from pg_class where oid='public.profiles'::regclass),
 'columns',(select jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid),'acl',coalesce((select jsonb_agg(v::text order by v::text) from unnest(a.attacl) x(v)),'[]'::jsonb)) order by a.attnum) from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid='public.profiles'::regclass and a.attnum>0 and not a.attisdropped),
 'policies',(select jsonb_agg(jsonb_build_object('name',polname,'cmd',polcmd,'permissive',polpermissive,'roles',(select jsonb_agg(case when r=0 then 'PUBLIC' else pg_get_userbyid(r) end order by r::regrole::text) from unnest(polroles) r),'using',pg_get_expr(polqual,polrelid),'check',pg_get_expr(polwithcheck,polrelid)) order by polname) from pg_policy where polrelid='public.profiles'::regclass),
 'helpers',(select jsonb_agg(jsonb_build_object('name',p.proname,'owner',pg_get_userbyid(p.proowner),'definer',p.prosecdef,'language',l.lanname,'volatility',p.provolatile,'strict',p.proisstrict,'returns',pg_get_function_result(p.oid),'args',pg_get_function_identity_arguments(p.oid),'source',replace(p.prosrc,chr(13),''),'config',p.proconfig,'acl',(select jsonb_agg(v::text order by v::text) from unnest(coalesce(p.proacl,acldefault('f',p.proowner))) a(v))) order by p.proname) from pg_proc p join pg_language l on l.oid=p.prolang where p.oid in ('public.is_current_user_owner_or_admin()'::regprocedure,'public.current_user_organization_id()'::regprocedure,'public.current_user_profile_id()'::regprocedure,'public.user_can_access_organization(uuid)'::regprocedure)),
 'callers',(select coalesce(jsonb_agg(to_jsonb(p) order by p.schemaname,p.tablename,p.policyname),'[]'::jsonb) from pg_policies p where coalesce(p.qual,'') ilike '%is_current_user_owner_or_admin%' or coalesce(p.with_check,'') ilike '%is_current_user_owner_or_admin%'),
 'function_callers',(select coalesce(jsonb_agg(jsonb_build_object('name',p.oid::regprocedure::text,'definition',replace(pg_get_functiondef(p.oid),chr(13),'')) order by p.oid::regprocedure::text),'[]'::jsonb) from pg_proc p where p.prokind in ('f','p') and p.prosrc ilike '%is_current_user_owner_or_admin%'),
 'view_callers',(select coalesce(jsonb_agg(jsonb_build_object('name',c.oid::regclass::text,'definition',pg_get_viewdef(c.oid,true)) order by c.oid::regclass::text),'[]'::jsonb) from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.relkind in ('v','m') and n.nspname not in ('pg_catalog','information_schema') and pg_get_viewdef(c.oid,true) ilike '%is_current_user_owner_or_admin%'),
 'roles',(select jsonb_agg(jsonb_build_object('name',rolname,'inherit',rolinherit,'bypass',rolbypassrls,'super',rolsuper,'login',rolcanlogin) order by rolname) from pg_roles where rolname in ('anon','authenticated','service_role','authenticator')),
 'memberships',(select coalesce(jsonb_agg(jsonb_build_object('role',pg_get_userbyid(m.roleid),'member',pg_get_userbyid(m.member),'inherit',m.inherit_option,'set',m.set_option,'admin',m.admin_option) order by pg_get_userbyid(m.member),pg_get_userbyid(m.roleid)),'[]'::jsonb) from pg_auth_members m where pg_get_userbyid(m.member) in ('anon','authenticated','service_role','authenticator')),
 'schema',(select jsonb_build_object('owner',pg_get_userbyid(nspowner),'acl',(select jsonb_agg(v::text order by v::text) from unnest(coalesce(nspacl,acldefault('n',nspowner))) a(v))) from pg_namespace where nspname='public'),
 'effective',(select jsonb_agg(jsonb_build_object('role',r.rolname,'privilege',p.p,'allowed',has_table_privilege(r.oid,'public.profiles',p.p),'usage',has_schema_privilege(r.oid,'public','USAGE')) order by r.rolname,p.p) from pg_roles r cross join (values('SELECT'),('INSERT'),('UPDATE'),('DELETE'),('TRUNCATE'),('REFERENCES'),('TRIGGER'),('MAINTAIN')) p(p) where r.rolname in ('anon','authenticated','service_role')),
 'effective_columns',(select jsonb_agg(jsonb_build_object('role',r.rolname,'column',a.attname,'privilege',p.p,'allowed',has_column_privilege(r.oid,a.attrelid,a.attnum,p.p)) order by r.rolname,a.attnum,p.p) from pg_roles r cross join pg_attribute a cross join (values('SELECT'),('INSERT'),('UPDATE'),('REFERENCES')) p(p) where r.rolname in ('anon','authenticated','service_role') and a.attrelid='public.profiles'::regclass and a.attnum>0 and not a.attisdropped)
);
